CREATE TABLE recipes (
    id              UUID PRIMARY KEY,
    name            VARCHAR(160) NOT NULL,
    search_text     VARCHAR(500) NOT NULL,
    servings        SMALLINT NOT NULL DEFAULT 4,
    enabled         BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_recipes_enabled ON recipes (enabled);
CREATE INDEX idx_recipes_search ON recipes (search_text);

CREATE TABLE recipe_ingredients (
    id              UUID PRIMARY KEY,
    recipe_id       UUID NOT NULL REFERENCES recipes (id) ON DELETE CASCADE,
    master_item_id  UUID NOT NULL REFERENCES master_items (id),
    quantity_label  VARCHAR(80) NOT NULL DEFAULT '',
    sort_order      SMALLINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_recipe_ingredient UNIQUE (recipe_id, master_item_id)
);

CREATE INDEX idx_recipe_ingredients_recipe ON recipe_ingredients (recipe_id, sort_order);

